using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "DrawSpecificTierCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Any/DrawSpecificTierCustomDescription", order = 0)]
public class DrawSpecificTierCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		DrawAction drawAction = battleAction as DrawAction;
		return Smart.Format(GetRawLocalizedDescription(battleAction), GetFinalAmountWithoutEquation(amountModified), drawAction.DiceSpecificTier.GetLocalizedDiceTierWithDie());
	}
}
